def H(t):return f'<h2>{t}</h2>'
def Pp(t):return f'<p>{t}</p>'
def UL(items,tag='ul'):return f'<{tag}>'+''.join(f'<li>{i}</li>' for i in items)+f'</{tag}>'
def TAB(rows,head):return '<table><tr>'+''.join(f'<th>{h}</th>' for h in head)+'</tr>'+''.join('<tr>'+''.join(f'<td>{c}</td>' for c in r)+'</tr>' for r in rows)+'</table>'
def tag(x,y,t,c='soft'):return R(x-15,y-10,30,20,c,5)+T(x,y+4,t,'t-s')


# ---- numbers (recomputed) ----
def crc16(bs):
    c=0xFFFF
    for x in bs:
        c^=x
        for _ in range(8):c=(c>>1)^0xA001 if c&1 else c>>1
    return c
req=bytes([1,3,0,0,0,2]);c=crc16(req);assert (c&255,c>>8)==(0xC4,0x0B)
bits=lambda n:n*11
t_req=bits(8)/9600;t_rsp=bits(9)/9600;sil=3.5*11/9600
tot=(t_req+t_rsp+2*sil)*1000
assert round(t_req*1000,1)==9.2 and round(t_rsp*1000,1)==10.3 and round(tot,1)==27.5 and round(20*tot/1000,2)==0.55
assert 0x00F0==240 and 240/10==24.0
assert 5+3+8==16 and 4+4+8==16 and 15*15*64==14400
